window.products.push({"id":726191,"name":"Kerr Quilted Crystal Jelly Jar 8oz Set of 12","category":"homeandappliances","retail price":30.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71W1wC9xMML._AC_SL1500_.jpg","description":"The Hearthmark 8 oz Jelly Jars are ideal for preserving food. They include lids, bands and labels to give you everything you need for canning. The glass jelly jars have an elegant quilted pattern that makes them nice as gifts. Use these multi-purpose jars for serving, creative decor and much more during the holidays or year round.","images":["https://m.media-amazon.com/images/I/71W1wC9xMML._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Kerr","source_asin":"B0042858E4","category_path":"Home & Kitchen"},"sku":"BM-726191","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0042858E4","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0042858E4","price_pending":true,"merchant_ready":false});
